  {"t": "Обязан ли водитель автомобиля, который движется по левой полосе, уступить дорогу в данной ситуации?", "o": ["Обязан.", "Не обязан."], "a": 1, "i": ["i18"]},
  {"t": "Кто должен уступить дорогу?", "o": ["Водитель легкового автомобиля.", "Водитель грузового автомобиля."], "a": 1, "i": ["i19"]}
