  {"t": "Как Вам следует поступить в данной ситуации?", "o": ["Проехать железнодорожный переезд без остановки перед знаком.", "Остановиться перед знаком и продолжить движение сразу же после проезда поезда.", "Остановиться перед знаком и продолжить движение, убедившись в отсутствии приближающегося поезда."], "a": 2, "i": ["i42"]},
  {"t": "Обязаны ли Вы уступить дорогу автобусу?", "o": ["Не обязаны.", "Обязаны."], "a": 1, "i": ["i4"]},
  {"t": "При наличии какого знака водитель должен уступить дорогу, если встречный разъезд затруднен?", "o": ["Только В.", "А и В.", "Б и В.", "Б и Г."], "a": 1, "i": ["i5"]}
